class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        best = float('-inf')
        for i in range(n):
            for j in range(i, n):
                inside = sorted(nums[i:j + 1])
                outside = sorted(nums[:i] + nums[j + 1:], reverse=True)
                cur = sum(inside)
                gain = 0
                for t in range(min(k, len(inside), len(outside))):
                    if outside[t] <= inside[t]:
                        break
                    gain += outside[t] - inside[t]
                best = max(best, cur + gain)
        return best

