class Solution {
public:
    long long maxSubarraySum(vector<int>& nums, int k) {
        int n = nums.size();
        long long best = LLONG_MIN;
        for (int i = 0; i < n; i++) {
            long long cur = 0;
            for (int j = i; j < n; j++) {
                cur += nums[j];
                vector<int> in(nums.begin() + i, nums.begin() + j + 1);
                vector<int> out(nums.begin(), nums.begin() + i);
                out.insert(out.end(), nums.begin() + j + 1, nums.end());
                sort(in.begin(), in.end());
                sort(out.rbegin(), out.rend());
                long long gain = 0;
                for (int t = 0; t < k && t < (int)in.size() && t < (int)out.size(); t++) {
                    if (out[t] <= in[t]) break;
                    gain += out[t] - in[t];
                }
                best = max(best, cur + gain);
            }
        }
        return best;
    }
};

