class Solution {
    public long maxSubarraySum(int[] nums, int k) {
        int n = nums.length;
        long best = Long.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            long cur = 0;
            for (int j = i; j < n; j++) {
                cur += nums[j];
                List<Integer> in = new ArrayList<>(), out = new ArrayList<>();
                for (int t = i; t <= j; t++) in.add(nums[t]);
                for (int t = 0; t < n; t++) if (t < i || t > j) out.add(nums[t]);
                Collections.sort(in);
                Collections.sort(out, Collections.reverseOrder());
                long gain = 0;
                for (int t = 0; t < k && t < in.size() && t < out.size(); t++) {
                    if (out.get(t) <= in.get(t)) break;
                    gain += out.get(t) - in.get(t);
                }
                best = Math.max(best, cur + gain);
            }
        }
        return best;
    }
}

