    let best = -Infinity;
    for (let i = 0; i < n; i++) {
        let cur = 0;
        for (let j = i; j < n; j++) {
            cur += nums[j];
            const inside = nums.slice(i, j + 1).sort((a, b) => a - b);
            const outside = nums.filter((_, t) => t < i || t > j).sort((a, b) => b - a);
            let gain = 0;
            for (let t = 0; t < k && t < inside.length && t < outside.length; t++) {
                if (outside[t] <= inside[t]) break;
                gain += outside[t] - inside[t];
            }
            best = Math.max(best, cur + gain);
        }
    }
    return best;
};

