class Solution {
public:
    long long maxSubarraySum(vector<int>& nums, int k) {
        int n = nums.size();
        multiset<int> in, out(nums.begin(), nums.end());
        long long cur = 0, best = LLONG_MIN;
        for (int left = 0; left < n; left++) {
            if (left > 0) {
                in.erase(in.find(nums[left - 1]));
                cur -= nums[left - 1];
            }
            for (int right = left; right < n; right++) {
                int x = nums[right];
                in.insert(x);
                out.erase(out.find(x));
                cur += x;
                long long gain = 0;
                auto hi = out.rbegin();
                auto lo = in.begin();
                for (int t = 0; t < k && hi != out.rend() && lo != in.end(); t++, ++hi, ++lo) {
                    if ((long long)*hi <= (long long)*lo) break;
                    gain += (long long)*hi - (long long)*lo;
                }
                best = max(best, cur + gain);
            }
        }
        return best;
    }
};

