import java.util.*;
class Solution {
    public long maxSubarraySum(int[] nums, int k) {
        int n = nums.length;
        TreeMap<Integer, Integer> in = new TreeMap<>(), out = new TreeMap<>();
        for (int x : nums) out.merge(x, 1, Integer::sum);
        long cur = 0, best = Long.MIN_VALUE;
        for (int left = 0; left < n; left++) {
            if (left > 0) {
                dec(in, nums[left - 1]);
                cur -= nums[left - 1];
            }
            for (int right = left; right < n; right++) {
                inc(in, nums[right]);
                dec(out, nums[right]);
                cur += nums[right];
                long gain = 0;
                Integer hi = out.lastKey(), lo = in.firstKey();
                for (int t = 0; t < k && hi != null && lo != null; t++) {
                    if (hi <= lo) break;
                    gain += hi - lo;
                    hi = out.lowerKey(hi);
                    lo = in.higherKey(lo);
                }
                best = Math.max(best, cur + gain);
            }
        }
        return best;
    }
    private void inc(TreeMap<Integer, Integer> tm, int x) { tm.merge(x, 1, Integer::sum); }
    private void dec(TreeMap<Integer, Integer> tm, int x) { if (tm.merge(x, -1, Integer::sum) == 0) tm.remove(x); }
}

