var maxSubarraySum = function(nums, k) {
    const n = nums.length;
    let best = -Infinity;
    const ins = (arr, x) => {
        let lo = 0, hi = arr.length;
        while (lo < hi) { const mid = (lo + hi) >> 1; if (arr[mid] < x) lo = mid + 1; else hi = mid; }
        arr.splice(lo, 0, x);
    };
    const rem = (arr, x) => {
        let lo = 0, hi = arr.length;
        while (lo < hi) { const mid = (lo + hi) >> 1; if (arr[mid] < x) lo = mid + 1; else hi = mid; }
        arr.splice(lo, 1);
    };
    const inside = [], outside = nums.slice().sort((a, b) => a - b);
    let cur = 0;
    for (let left = 0; left < n; left++) {
        if (left > 0) { rem(inside, nums[left - 1]); cur -= nums[left - 1]; }
        for (let right = left; right < n; right++) {
            const x = nums[right];
            ins(inside, x); rem(outside, x); cur += x;
            let gain = 0;
            for (let t = 0; t < k && t < inside.length && t < outside.length; t++) {
                const a = outside[outside.length - 1 - t], b = inside[t];
                if (a <= b) break;
                gain += a - b;
            }
            best = Math.max(best, cur + gain);
        }
    }
    return best;
};
